// Organize questions by category and audience

record InterviewQuestion(
    String category,
    String question,
    String whyItWorks
) {}

var strongQuestions = List.of(
    new InterviewQuestion(
        "Onboarding and mentorship",
        "What does the onboarding process look like for a junior Java developer, and how is mentorship structured?",
        "Shows you're thinking about how you'll ramp up and value learning from experienced engineers"
    ),
    new InterviewQuestion(
        "Day-to-day work",
        "Can you walk me through what a typical sprint looks like for the team—how do you prioritize work and collaborate?",
        "Reveals actual work environment and whether you'll be thrown into chaos or have clear structure"
    ),
    new InterviewQuestion(
        "Technical challenges",
        "What are some of the biggest technical challenges the team is working on right now or in the next quarter?",
        "Shows you're thinking about real problems you'd tackle, not just abstract job duties"
    ),
    new InterviewQuestion(
        "Success criteria",
        "What would success look like for someone in this role after the first six months?",
        "Demonstrates you're already thinking about how to contribute effectively and meet expectations"
    ),
    new InterviewQuestion(
        "Interviewer experience",
        "What's kept you at this company, and what's been most rewarding about your time here?",
        "Personal questions build rapport and give genuine insight into culture and retention factors"
    )
);
```

