// Structure your response: Legitimate concern + Mitigation + Commitment

record DealBreaker(
    String concern,
    String whyItMatters,
    String howYouWouldAddress
) {}

var legitimateDealBreakers = List.of(
    new DealBreaker(
        "Lack of learning opportunities",
        "As a fresher, my priority is building strong fundamentals. If I felt stagnant with no mentorship or challenging work after giving it a fair shot",
        "I'd raise this proactively with my manager first and ask for stretch assignments or learning resources before considering leaving"
    ),
    new DealBreaker(
        "Major mismatch between job description and reality",
        "If the role turned out to be significantly different from what we discussed—like being pure maintenance work instead of new development",
        "I'd have an honest conversation about expectations and see if there's a path to the work we originally discussed"
    ),
    new DealBreaker(
        "Poor management or toxic environment",
        "If I experienced consistent lack of support, unclear expectations, or an environment where I couldn't raise concerns constructively",
        "I believe in giving feedback and trying to improve situations before leaving, but sustained toxicity would make me consider other options"
    )
);

// Close with commitment
String demonstrateCommitment() {
    return "That said, I'm choosing this role deliberately based on what I've learned "
         + "about the team, the tech stack, and the growth opportunities. "
         + "I'm committed to making this work and contributing meaningfully.";
}
